from collections import deque
import sys

class Scan:
    def __init__(self):
        self.buffer = deque()

    def next(self, typ=int):
        while True:
            if self.buffer:
                token = self.buffer.popleft()
                return typ(token)
            line = sys.stdin.readline()
            if not line:
                raise EOFError("Fail to read")
            self.buffer = deque(line.split())

def _main():
    scan = Scan()
    res = 0
    n = scan.next(int)
    m = scan.next(int)
    limit = max(n, m)
    for i in range(limit + 1):
        for j in range(limit + 1):
            if i * i + j == n and i + j * j == m:
                res += 1
    print(res)

def main():
    _main()

if __name__ == "__main__":
    main()

